import{_ as d,o as r,c as a,aj as e}from"./chunks/framework.Cn87zHeG.js";const u=JSON.parse('{"title":"故障速查","description":"","frontmatter":{"outline":[2,3]},"headers":[],"relativePath":"faq/troubleshooting.md","filePath":"faq/troubleshooting.md"}'),o={name:"faq/troubleshooting.md"};function i(h,t,l,n,s,c){return r(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="故障速查" tabindex="-1">故障速查 <a class="header-anchor" href="#故障速查" aria-label="Permalink to &quot;故障速查&quot;">​</a></h1><p>需要核对后台进程或重启对应模块时，见<a href="./../diagnostics/services.html">机内服务与重启</a>，其中列出了服务名、职责、状态查询和日志命令。</p><h2 id="网络-配网" tabindex="-1">网络 / 配网 <a class="header-anchor" href="#网络-配网" aria-label="Permalink to &quot;网络 / 配网&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>排查</th></tr></thead><tbody><tr><td>配网页 <code>10.42.0.2:8080</code> 打不开</td><td>网线没插好；或配网服务未启动</td></tr><tr><td>配网页 <code>192.168.60.1:8080</code> 打不开</td><td>没连上机器人热点；或热点服务异常</td></tr><tr><td>页面能开但一直 loading</td><td>服务在跑但可能异常，联系技术支持</td></tr><tr><td>WiFi 列表空白</td><td>信号太差扫不到；点「刷新扫描」重试；仍空白联系技术支持</td></tr><tr><td>连 WiFi 失败（activation failed）</td><td>密码错 / 信号弱 / WiFi 类型不支持</td></tr><tr><td>连 WiFi 失败（timeout）</td><td>30 秒内没连上，通常是信号问题</td></tr><tr><td>型号 / 序列号显示&quot;未读取到&quot;</td><td>出厂未烧录该信息属正常；如需确认联系技术支持</td></tr><tr><td>软件版本显示&quot;未读取到&quot;</td><td>版本文件缺失，联系技术支持</td></tr></tbody></table><h2 id="ota-升级" tabindex="-1">OTA 升级 <a class="header-anchor" href="#ota-升级" aria-label="Permalink to &quot;OTA 升级&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>排查</th></tr></thead><tbody><tr><td>上传卡住 / 失败</td><td>大包上传耗时长，看进度条是否在动；用热点上传易断，重试；上传后确认列表出现该文件</td></tr><tr><td>升级触发后 20 秒无反应</td><td>工具会自动提示，可重试；多次无效联系技术支持</td></tr><tr><td>升级失败</td><td>看升级日志最后一行的失败阶段，联系技术支持并提供日志</td></tr><tr><td>升级中误关了页面</td><td>不影响升级，重新打开会自动恢复进度；<strong>但绝不要断电</strong></td></tr></tbody></table><h2 id="测试工具-运动" tabindex="-1">测试工具 / 运动 <a class="header-anchor" href="#测试工具-运动" aria-label="Permalink to &quot;测试工具 / 运动&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>第一步排查</th></tr></thead><tbody><tr><td>测试页打不开</td><td>确认机器人已上电、网络连通</td></tr><tr><td>顶部全是红 chip</td><td>算法栈未启动，联系厂商技术支持</td></tr><tr><td>点开始建图无反应</td><td>看顶部 <code>/slam/cmd</code> 是否红/黄，联系技术支持</td></tr><tr><td>地图一直空白</td><td>看 <code>/map</code> 是否有数据，可能雷达未启动</td></tr><tr><td>提示&quot;导航任务进行中&quot;</td><td>先到导航页取消任务再试</td></tr><tr><td>定位 <code>/slam/pose</code> 始终红</td><td>定位未启动或 IMU/雷达异常，联系技术支持</td></tr><tr><td>导航不动</td><td>确认定位是否成功、目标点是否在地图内</td></tr><tr><td>机械臂状态一直 idle</td><td>机械臂节点未启动，联系技术支持</td></tr><tr><td>出现堵转 / 升降报警</td><td>先停止操作、排除机械卡阻，再点「清除升降报警」</td></tr></tbody></table><blockquote><p>💡 遇到无法判断的问题，优先在「系统诊断 → 接口健康」页点 <strong>复制诊断信息</strong>，连同操作步骤一起发给厂商技术支持。</p></blockquote>',9)])])}const _=d(o,[["render",i]]);export{u as __pageData,_ as default};
